// Fetch all sources — Silver Spirit + Nova + Ray + Perx (authenticated)
const fs = require('fs');

// Load Perx cookies for authenticated scraping
let perxCookieStr = '';
try {
  const cookieData = JSON.parse(fs.readFileSync('/home/john/Thunderbird/creds/perx_cookies.json', 'utf8'));
  perxCookieStr = cookieData.cookies
    .filter(c => c.domain.includes('perx.com') || c.domain.includes('cloudflare.com'))
    .map(c => `${c.name}=${c.value}`).join('; ');
} catch (e) { perxCookieStr = ''; }

const sources = [
  // Silver Spirit — confirmed voyages
  { name: 'Silver Spirit Leg 1 (Lisbon-Copenhagen)', url: 'https://www.silversea.com/destinations/northern-europe-british-isles-cruise/lisbon-to-copenhagen-sl270505016.html', type: 'silversea', ship: 'spirit' },
  { name: 'Silver Spirit Leg 2 (CPH-Norway-CPH)', url: 'https://www.silversea.com/destinations/northern-europe-british-isles-cruise/copenhagen-to-copenhagen-sl270521015.html', type: 'silversea', ship: 'spirit' },
  // Silver Nova — May/Jun 2027 filter
  { name: 'Silver Nova May-Jun 2027', url: 'https://www.silversea.com/find-a-voyage.html?voyageType=classic&ship=NV&departureFrom=2027-05&departureTo=2027-06', type: 'deals', ship: 'nova' },
  // Silver Ray — May/Jun 2027 filter
  { name: 'Silver Ray May-Jun 2027', url: 'https://www.silversea.com/find-a-voyage.html?voyageType=classic&ship=RA&departureFrom=2027-05&departureTo=2027-06', type: 'deals', ship: 'ray' },
  // Silversea Deals (all 3 ships)
  { name: 'Silversea Deals (Spirit)', url: 'https://www.silversea.com/find-a-voyage.html?voyageType=classic&ship=SI&departureFrom=2027-04&departureTo=2027-07', type: 'deals', ship: 'spirit' },
  // Perx — authenticated TA rate scrape
  { name: 'Perx Silversea (all ships)', url: 'https://www.perx.com/cruise/silversea', type: 'perx', ship: 'all' },
  { name: 'Perx Silver Spirit', url: 'https://www.perx.com/cruise/silversea/silver-spirit', type: 'perx', ship: 'spirit' },
  { name: 'Perx Silver Nova', url: 'https://www.perx.com/cruise/silversea/silver-nova', type: 'perx', ship: 'nova' },
  { name: 'Perx Silver Ray', url: 'https://www.perx.com/cruise/silversea/silver-ray', type: 'perx', ship: 'ray' },
  // Exchange rate
  { name: 'Exchange Rate EUR/USD', url: 'https://open.er-api.com/v6/latest/EUR', type: 'fx', ship: 'all' },
  // CruiseCritic reviews
  { name: 'CruiseCritic Silver Spirit', url: 'https://www.cruisecritic.com/reviews/review.cfm?ShipID=743', type: 'review', ship: 'spirit' },
  { name: 'CruiseCritic Silver Nova', url: 'https://www.cruisecritic.com/reviews/review.cfm?ShipID=927', type: 'review', ship: 'nova' },
  { name: 'CruiseCritic Silver Ray', url: 'https://www.cruisecritic.com/reviews/review.cfm?ShipID=928', type: 'review', ship: 'ray' },
  // Interline
  { name: 'ID90 Travel', url: 'https://www.id90travel.com/', type: 'interline', ship: 'all' }
];

const results = [];
const defaultHeaders = {
  'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,application/json,*/*;q=0.8',
  'Accept-Language': 'en-US,en;q=0.9'
};

for (const src of sources) {
  try {
    const headers = { ...defaultHeaders };
    if (src.type === 'perx' && perxCookieStr) {
      headers['Cookie'] = perxCookieStr;
    }
    const resp = await fetch(src.url, { headers, signal: AbortSignal.timeout(15000) });
    const body = await resp.text();
    results.push({ name: src.name, url: src.url, type: src.type, ship: src.ship, status: resp.status, body: body.substring(0, 50000), ok: resp.ok });
  } catch (err) {
    results.push({ name: src.name, url: src.url, type: src.type, ship: src.ship, status: 0, body: '', ok: false, error: err.message });
  }
}

return [{ json: { sources: results, fetchedAt: new Date().toISOString() } }];

const data = $input.first().json;
const sources = data.sources;
const results = { legs: {}, fx: null, signals: [], errors: [] };

// --- Parse Silversea voyage pages ---
for (const src of sources.filter(s => s.type === 'silversea')) {
  const voyageId = src.url.includes('SL270505016') ? 'LEG1' : 'LEG2';
  if (!src.ok) {
    results.errors.push(`${src.name}: HTTP ${src.status} ${src.error || ''}`);
    results.legs[voyageId] = { name: src.name, price: null, raw: 'FETCH_FAILED' };
    continue;
  }
  let price = null;
  let raw = 'NOT_PARSEABLE';

  // Try JSON-LD
  const jsonLdMatch = src.body.match(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/i);
  if (jsonLdMatch) {
    try {
      const ld = JSON.parse(jsonLdMatch[1]);
      if (ld.offers) {
        const offer = Array.isArray(ld.offers) ? ld.offers[0] : ld.offers;
        price = parseFloat(offer.price || offer.lowPrice);
        raw = `JSON-LD: ${offer.priceCurrency || 'USD'} ${price}`;
      }
    } catch (e) { /* JSON-LD parse failed, try regex */ }
  }

  // Regex fallback: look for price patterns
  if (!price) {
    // Pattern: "from $X,XXX" or "starting at $X,XXX" or "USD X,XXX"
    const pricePatterns = [
      /(?:from|starting\s+at|price)[^$]*\$([\d,]+)/i,
      /USD\s*([\d,]+)/i,
      /"price"\s*:\s*"?([\d,.]+)/i,
      /"lowPrice"\s*:\s*"?([\d,.]+)/i,
      /data-price="([\d,.]+)"/i,
      /fare[^$]*\$([\d,]+)/i
    ];
    for (const pat of pricePatterns) {
      const m = src.body.match(pat);
      if (m) {
        price = parseFloat(m[1].replace(/,/g, ''));
        raw = `Regex: USD ${price}`;
        break;
      }
    }
  }

  // Check for TA/interline rate signals
  const taSignals = [
    /travel\s*(?:advisor|agent|professional)\s*(?:rate|fare|pricing)/i,
    /interline/i,
    /industry\s*rate/i,
    /trade\s*rate/i,
    /reduced\s*(?:rate|fare)/i
  ];
  for (const pat of taSignals) {
    if (pat.test(src.body)) {
      results.signals.push(`${src.name}: TA/interline rate signal detected (${pat.source})`);
    }
  }

  if (!price) raw = 'NOT_PARSEABLE (JS-rendered SPA — no server-side price)';
  results.legs[voyageId] = { name: src.name, price, raw };
}

// --- Parse Deals page ---
const dealsSrc = sources.find(s => s.type === 'deals');
if (dealsSrc && dealsSrc.ok) {
  const promoPatterns = [
    /(?:save|discount|offer|deal|bonus|complimentary|free)[^.]{0,120}/gi
  ];
  for (const pat of promoPatterns) {
    const matches = dealsSrc.body.match(pat);
    if (matches) {
      results.signals.push(`Silversea Deals: ${matches.slice(0, 3).map(m => m.trim().substring(0, 100)).join(' | ')}`);
    }
  }
} else if (dealsSrc) {
  results.errors.push(`Deals page: HTTP ${dealsSrc.status}`);
}

// --- Parse FX rate ---
const fxSrc = sources.find(s => s.type === 'fx');
if (fxSrc && fxSrc.ok) {
  try {
    const fxData = JSON.parse(fxSrc.body);
    results.fx = {
      eurUsd: fxData.rates?.USD || null,
      fetchedAt: fxData.time_last_update_utc || data.fetchedAt
    };
  } catch (e) {
    results.errors.push('FX parse error: ' + e.message);
  }
} else {
  results.errors.push('FX fetch failed');
}

// --- Parse interline sources ---
for (const src of sources.filter(s => s.type === 'interline')) {
  if (!src.ok) {
    results.errors.push(`${src.name}: HTTP ${src.status} — ${src.error || 'unreachable'}`);
    continue;
  }
  const interlinePatterns = [
    /silversea/i,
    /silver\s*spirit/i,
    /SL2705/i,
    /lisbon.*copenhagen/i,
    /scandinavia/i
  ];
  for (const pat of interlinePatterns) {
    if (pat.test(src.body)) {
      results.signals.push(`${src.name}: Silversea mention detected`);
      break;
    }
  }
}

// --- Parse CruiseCritic ---
const ccSrc = sources.find(s => s.type === 'review');
if (ccSrc && ccSrc.ok) {
  const ratingMatch = ccSrc.body.match(/(?:overall|rating)[^\d]{0,30}([\d.]+)\s*(?:out\s*of|\/)\s*5/i);
  if (ratingMatch) {
    results.signals.push(`CruiseCritic Silver Spirit rating: ${ratingMatch[1]}/5`);
  }
}

results.fetchedAt = data.fetchedAt;
return [{ json: results }];

const fs = require('fs');
const data = $input.first().json;
const staticData = $workflow.staticData || {};
const prev = staticData.lastPrices || {};
const now = new Date();
const weekOf = now.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

// --- Price comparison ---
const changes = [];
for (const [legId, legData] of Object.entries(data.legs || {})) {
  if (legData.price && prev[legId]) {
    const delta = legData.price - prev[legId];
    const pctChange = ((delta / prev[legId]) * 100).toFixed(1);
    if (Math.abs(parseFloat(pctChange)) > 0.1) {
      const direction = delta > 0 ? 'UP' : 'DOWN';
      const alert = Math.abs(parseFloat(pctChange)) > 5 ? ' ALERT' : '';
      changes.push({
        leg: legData.name,
        prev: prev[legId],
        current: legData.price,
        delta,
        pctChange,
        direction,
        alert
      });
    }
  }
}

// --- Update staticData ---
const newPrices = {};
for (const [legId, legData] of Object.entries(data.legs || {})) {
  if (legData.price) newPrices[legId] = legData.price;
}
$workflow.staticData = { lastPrices: { ...prev, ...newPrices }, lastRun: now.toISOString() };

// --- FX display ---
const fxDisplay = data.fx?.eurUsd ? `EUR/USD: ${data.fx.eurUsd.toFixed(4)}` : 'EUR/USD: unavailable';

// --- Build HTML email ---
const alertBanner = changes.some(c => c.alert) 
  ? '<div style="background:#d32f2f;color:#fff;padding:12px 20px;font-size:16px;font-weight:bold;border-radius:4px;margin-bottom:16px;">PRICE MOVEMENT ALERT &mdash; >5% change detected</div>'
  : '';

const priceRows = Object.entries(data.legs || {}).map(([id, leg]) => {
  const change = changes.find(c => c.leg === leg.name);
  const changeCell = change 
    ? `<span style="color:${change.direction === 'DOWN' ? '#2e7d32' : '#d32f2f'};font-weight:bold;">${change.direction} $${Math.abs(change.delta).toFixed(0)} (${change.pctChange}%)${change.alert}</span>`
    : '<span style="color:#666;">No change</span>';
  const priceCell = leg.price 
    ? `$${leg.price.toLocaleString()}` 
    : `<span style="color:#999;">${leg.raw}</span>`;
  return `<tr><td style="padding:8px 12px;border-bottom:1px solid #e0e0e0;">${leg.name}</td><td style="padding:8px 12px;border-bottom:1px solid #e0e0e0;">${priceCell}</td><td style="padding:8px 12px;border-bottom:1px solid #e0e0e0;">${changeCell}</td></tr>`;
}).join('');

const signalRows = (data.signals || []).length > 0
  ? data.signals.map(s => `<tr><td style="padding:6px 12px;border-bottom:1px solid #e0e0e0;">${s}</td></tr>`).join('')
  : '<tr><td style="padding:6px 12px;color:#999;">No signals detected this week</td></tr>';

const errorRows = (data.errors || []).length > 0
  ? `<div style="margin-top:16px;padding:12px;background:#fff3e0;border-left:4px solid #ff9800;border-radius:4px;"><strong>Source Issues:</strong><ul style="margin:8px 0 0 0;">${data.errors.map(e => `<li>${e}</li>`).join('')}</ul></div>`
  : '';

const nextMonday = new Date(now.getTime() + 7*24*60*60*1000);
const nextMondayStr = nextMonday.toLocaleDateString('en-US', { month: 'long', day: 'numeric' });
const prevPricesNote = Object.keys(prev).length > 0 ? 'Yes (' + Object.keys(prev).join(', ') + ')' : 'First run &mdash; baseline established';

const html = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family:Georgia,serif;background:#f7f3ea;margin:0;padding:0;">
<div style="max-width:680px;margin:0 auto;background:#ffffff;border:1px solid #ddd;">
  <div style="background:#1a237e;color:#ffffff;padding:20px 24px;">
    <h1 style="margin:0;font-size:22px;font-weight:normal;">Silversea Spring 2027 Watch</h1>
    <p style="margin:4px 0 0;font-size:13px;color:#b0bec5;">Week of ${weekOf} &bull; ${fxDisplay}</p>
  </div>
  <div style="padding:20px 24px;">
    ${alertBanner}
    <h2 style="color:#1a237e;font-size:16px;margin:0 0 12px;border-bottom:2px solid #1a237e;padding-bottom:6px;">Silver Spirit &mdash; Target Voyages</h2>
    <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px;">
      <tr style="background:#f5f5f5;"><th style="padding:8px 12px;text-align:left;">Voyage</th><th style="padding:8px 12px;text-align:left;">Price (pp)</th><th style="padding:8px 12px;text-align:left;">WoW Change</th></tr>
      ${priceRows}
    </table>
    <div style="font-size:13px;color:#555;margin-bottom:20px;padding:10px;background:#f9f9f9;border-radius:4px;">
      <strong>Leg 1:</strong> SL270505016 &bull; Lisbon &rarr; Copenhagen &bull; May 5&ndash;21, 2027 &bull; 16 nights<br>
      <strong>Leg 2:</strong> SL270521015 &bull; Copenhagen &rarr; Norway &rarr; CPH &bull; May 21&ndash;Jun 5, 2027 &bull; 15 nights
    </div>
    <h2 style="color:#1a237e;font-size:16px;margin:0 0 12px;border-bottom:2px solid #1a237e;padding-bottom:6px;">Signal Detection</h2>
    <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px;">
      ${signalRows}
    </table>
    <h2 style="color:#1a237e;font-size:16px;margin:0 0 12px;border-bottom:2px solid #1a237e;padding-bottom:6px;">Sources Checked (7)</h2>
    <div style="font-size:13px;color:#555;line-height:1.8;">
      1. Silversea SL270505016 (Leg 1 direct page)<br>
      2. Silversea SL270521015 (Leg 2 direct page)<br>
      3. Silversea Deals &amp; Promotions (Silver Spirit filter)<br>
      4. Exchange Rate API (EUR/USD live)<br>
      5. CruiseCritic Silver Spirit reviews<br>
      6. Perx Travel / Interline Rate Desk<br>
      7. ID90 Travel
    </div>
    ${errorRows}
    <div style="margin-top:24px;padding-top:16px;border-top:1px solid #ddd;font-size:12px;color:#999;">
      Automated by Thunderbird Wing &bull; Dreams2Memories Travel, LLC<br>
      Next scan: Monday ${nextMondayStr}<br>
      Previous prices stored: ${prevPricesNote}
    </div>
  </div>
</div>
</body>
</html>`;

const hasAlert = changes.some(c => c.alert);
const subject = hasAlert
  ? '[ALERT] Silversea Spring 2027 Watch - ' + weekOf
  : 'Silversea Spring 2027 Watch - ' + weekOf;

// Write payload to temp file for the email sender script
const payload = JSON.stringify({ html, subject });
fs.writeFileSync('/tmp/silversea_report_payload.json', payload, 'utf8');

return [{ json: { payloadFile: '/tmp/silversea_report_payload.json', subject, hasAlert, changes, signalCount: (data.signals || []).length, errorCount: (data.errors || []).length } }];

const { execSync } = require('child_process');
const payloadFile = $input.first().json.payloadFile;
try {
  const output = execSync(`cd /home/john/Thunderbird && python3 scripts/send_silversea_report.py ${payloadFile}`, { encoding: 'utf8', timeout: 30000 });
  return [{ json: { status: 'sent', output: output.trim() } }];
} catch (err) {
  return [{ json: { status: 'error', error: err.message, stderr: err.stderr } }];
}
